#!/data/data/com.termux/files/usr/bin/bash
set -e
cd ~/elonuz_v3
echo "🚀 E'lonUz V4 yangilanishi..."
[ -f backup_v4/server.js ] || { echo "❌ Backup topilmadi"; exit 1; }
cp server.js server_before_v4.js
cp public/index.html public/index_before_v4.html

# Email ustunini qo'shish
sed -i '/ALTER TABLE users ADD COLUMN IF NOT EXISTS password TEXT;/a\    ALTER TABLE users ADD COLUMN IF NOT EXISTS email TEXT;' server.js

# V4 frontend
cat > public/index.html <<'HTML'
<!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>E'lonUz V4</title>
<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f4f6f5;color:#172018;padding-bottom:70px}header{background:#fff;padding:14px;position:sticky;top:0;z-index:5;border-bottom:1px solid #ddd}.top{max-width:900px;margin:auto;display:flex;justify-content:space-between}.logo{font-size:23px;font-weight:bold;color:#166534}.container{max-width:900px;margin:auto;padding:15px}.hero{background:linear-gradient(135deg,#166534,#22c55e);color:#fff;padding:20px;border-radius:18px}input,select,textarea{width:100%;padding:12px;border:1px solid #ddd;border-radius:10px;font-size:16px;margin:5px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;margin-top:12px}.card,.panel{background:#fff;padding:15px;border-radius:15px;box-shadow:0 2px 8px #0001}.price{font-weight:bold;color:#166534;font-size:20px}.muted{color:#68706a;font-size:14px}.cats{display:flex;gap:7px;overflow:auto;padding:14px 0}.cats button{white-space:nowrap}button{border:0;padding:10px 12px;border-radius:10px;font-weight:bold;cursor:pointer}.primary{background:#166534;color:#fff}.danger{background:#dc2626;color:#fff}.modal{display:none;position:fixed;inset:0;background:#0008;padding:18px;z-index:20}.box{background:#fff;max-width:500px;margin:30px auto;padding:18px;border-radius:16px}.hidden{display:none!important}.view{display:none}.view.active{display:block}.bottom{position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #ddd;display:flex;justify-content:space-around;padding:7px;z-index:10}.bottom button{background:none;font-size:12px}.emoji{font-size:40px}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}@media(min-width:650px){.bottom{display:none}body{padding-bottom:0}}
</style></head><body>
<header><div class="top"><div class="logo">🇺🇿 E'lonUz V4</div><button class="primary" onclick="openAd()">➕ E'lon</button></div></header>
<main class="container">
<section id="home" class="view active"><div class="hero"><h2>O'zbekistondagi e'lonlar</h2><input id="search1" placeholder="🔍 Nima qidiryapsiz?" oninput="render()"></div><div id="cats" class="cats"></div><h2 id="pageTitle">Yangi e'lonlar</h2><div id="ads" class="grid"></div></section>
<section id="searchView" class="view"><h2>🔍 Qidirish</h2><input id="search2" placeholder="Qidirish..." oninput="render()"><select id="regionFilter" onchange="render()"><option value="">Barcha hududlar</option><option>Toshkent</option><option>Andijon</option><option>Samarqand</option><option>Buxoro</option><option>Farg'ona</option><option>Namangan</option></select><div id="ads2" class="grid"></div></section>
<section id="categoryView" class="view"><h2>📂 Kategoriyalar</h2><div id="categoryList" class="panel"></div></section>
<section id="profileView" class="view"><h2>👤 Profil</h2><div id="profile" class="panel"></div></section></main>
<nav class="bottom"><button onclick="nav('home')">🏠<br>Bosh sahifa</button><button onclick="nav('searchView')">🔍<br>Qidirish</button><button onclick="openAd()">➕<br>E'lon</button><button onclick="nav('categoryView')">📂<br>Kategoriya</button><button onclick="nav('profileView')">👤<br>Profil</button></nav>
<div id="authModal" class="modal"><div class="box"><h2 id="authTitle">Kirish</h2><div id="nameField" class="hidden"><input id="authName" placeholder="Ismingiz"></div><div id="emailField" class="hidden"><input id="authEmail" placeholder="Email"></div><input id="authPhone" placeholder="+998901234567"><input id="authPassword" type="password" placeholder="Parol"><div class="actions"><button class="primary" onclick="submitAuth()">Davom etish</button><button onclick="toggleAuth()">Rejim</button></div></div></div>
<div id="adModal" class="modal"><div class="box"><h2>➕ Yangi e'lon</h2><form id="adForm"><input id="adTitle" placeholder="Sarlavha" required><input id="adPrice" type="number" placeholder="Narx" required><select id="adCategory"></select><input id="adRegion" placeholder="Viloyat" required><input id="adCity" placeholder="Shahar"><textarea id="adDescription" placeholder="Tavsif"></textarea><input id="adImage" value="📦"><button class="primary">Saqlash</button></form></div></div>
<script>
const C=["Telefonlar","Avtomobillar","Texnika","Uy-joy","Ish","Boshqa"];let ADS=[],activeCat="",authMode="login";const token=()=>localStorage.getItem("elonuz_token"),user=()=>{try{return JSON.parse(localStorage.getItem("elonuz_user"))}catch(e){return null}},headers=()=>({"Content-Type":"application/json","Authorization":"Bearer "+token()});function esc(x){let d=document.createElement("div");d.textContent=x||"";return d.innerHTML}function nav(id){document.querySelectorAll(".view").forEach(x=>x.classList.remove("active"));document.getElementById(id).classList.add("active");if(id==="profileView")showProfile();if(id==="categoryView")showCategories()}function makeCategories(){cats.innerHTML='<button onclick="setCat(\'\')">Hammasi</button>'+C.map(x=>'<button onclick="setCat(\''+x+'\')">'+x+'</button>').join("");adCategory.innerHTML=C.map(x=>'<option>'+x+'</option>').join("")}function setCat(x){activeCat=x;nav("home");render()}async function loadAds(){let r=await fetch("/api/ads");ADS=await r.json();render()}function render(){let s=(search1.value+" "+search2.value).toLowerCase(),rg=regionFilter.value,f=ADS.filter(a=>(a.title+" "+(a.description||"")).toLowerCase().includes(s)&&(!activeCat||a.category===activeCat)&&(!rg||a.region===rg)),h=f.length?f.map(a=>'<div class="card"><div class="emoji">'+esc(a.image||"📦")+'</div><h3>'+esc(a.title)+'</h3><div class="price">'+Number(a.price).toLocaleString("uz-UZ")+" so'm</div><div class="muted">📂 '+esc(a.category||"Boshqa")+' • 📍 '+esc(a.region||"")+'</div><p>'+esc(a.description||"")+'</p><div class="muted">👤 '+esc(a.seller||"")+'</div></div>').join(""):"<div class='panel'>📭 E'lon topilmadi</div>";ads.innerHTML=h;ads2.innerHTML=h}function openAd(){if(!token()){authModal.style.display="block";updateAuth();return}adModal.style.display="block"}function toggleAuth(){authMode=authMode==="login"?"register":"login";updateAuth()}function updateAuth(){let r=authMode==="register";authTitle.textContent=r?"Ro'yxatdan o'tish":"Kirish";nameField.classList.toggle("hidden",!r);emailField.classList.toggle("hidden",!r)}async function submitAuth(){let b=authMode==="register"?{name:authName.value,phone:authPhone.value,password:authPassword.value}:{phone:authPhone.value,password:authPassword.value},r=await fetch(authMode==="register"?"/api/register":"/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)}),x=await r.json();if(!r.ok)return alert("❌ "+x.error);localStorage.setItem("elonuz_token",x.token);localStorage.setItem("elonuz_user",JSON.stringify(x.user));authModal.style.display="none";alert("🎉 Muvaffaqiyatli!")}adForm.onsubmit=async e=>{e.preventDefault();let d={title:adTitle.value,price:adPrice.value,category:adCategory.value,region:adRegion.value,city:adCity.value,description:adDescription.value,image:adImage.value},r=await fetch("/api/ads",{method:"POST",headers:headers(),body:JSON.stringify(d)}),x=await r.json();if(!r.ok)return alert("❌ "+x.error);adModal.style.display="none";loadAds();alert("🎉 Saqlandi!")};function showProfile(){let u=user();profile.innerHTML=u?'<h3>👤 '+esc(u.name)+'</h3><p>📞 '+esc(u.phone)+'</p><button onclick="myAds()">📦 Mening e\'lonlarim</button><button class="danger" onclick="logout()">Chiqish</button>':'<p>Akkauntingizga kiring.</p><button class="primary" onclick="openAd()">Kirish</button>'}async function myAds(){let r=await fetch("/api/my-ads",{headers:headers()});ADS=await r.json();pageTitle.textContent="📦 Mening e'lonlarim";nav("home");render()}function logout(){localStorage.clear();loadAds();nav("home")}function showCategories(){categoryList.innerHTML=C.map(x=>'<button onclick="setCat(\''+x+'\')">📂 '+x+'</button>').join(" ")}makeCategories();loadAds();
</script></body></html>
HTML
echo "✅ V4 o'rnatildi!"
echo "📌 Endi: git add . && git commit -m 'E lonUz V4 update' && git push"
